      "matchedTopic": "科学前沿动态",
      "rawText": "首页 > 科研进展 月球已经不存在全球性磁场，但月面依旧留存磁化痕迹。它们究竟来自月球内部，还是天体撞击产生的短暂磁场？要解开这个问题，科学家需要找到可靠的“记录者”。而解开谜题的钥匙，就藏在月壤的磁性矿物里。 近日，中国科学院合肥物质科学研究院、地质与地球物理研究所等在嫦娥六号返回月壤磁性矿物中，发现 一种通常只在高温条件下稳定存在的铁——γ-Fe，且每个小颗粒里还住着一个稳定的“磁漩涡” 。 天体撞击月球时，月表部分物质熔化，冷却后形成玻璃状碎屑。 这些碎屑赋存不同类型的铁，可能记录撞击过程不同阶段的磁场信息。破译这些“磁记录”，能够帮助科研人员分辨月球磁场线索究竟源自内部活动还是撞击事件。 科研团队在月壤中找到含金属铁的撞击玻璃颗粒，并在这些撞击玻璃中发现大量纳米尺度金属铁颗粒。其中部分颗粒的主要铁相是理论上无法在室温存在的γ-Fe。 γ-Fe是铁的“高温形态”，与人们日常熟悉的铁是 α-Fe不同。它 一般只在900多摄氏度以上稳定存在，冷却后就会变回α-Fe。在地球上，要在室温留住γ-Fe，通常要依靠特殊合金。 月球撞击玻璃为什么能锁住γ-Fe？研究推测， 撞击后的快速冷却、微",
