      "matchedTopic": "科学前沿动态",
      "rawText": "首页 > 科研进展 在脑科学研究中，精确“开启”或“关闭”特定神经活动，直接决定科研人员解析大脑功能的能力。但常见的光敏蛋白大多依赖可见光，而可见光穿透力有限。传统方案只能在颅内植入光纤，把光送入脑深部，易对脑组织造成损伤。 近年来出现的近红外光遗传学，能够“隔着颅骨”递光，但仍需持续照射来维持神经元活动，长时间照射带来的光热累积也不容忽视。如何在不植入、也不持续照光的前提下灵活调控神经活动，一直缺少理想方案。 近日，中国科学院脑科学与智能技术卓越创新中心 开发出一种名为“双近红外开关”（Dual-NIR Switch）的神经调控技术，依靠两束穿颅近红外光，分别“开启”和“终止”神经元兴奋信号 。实验中，这套技术无需给小鼠植入光纤，也不用在它头部佩戴设备，可在小鼠自由活动状态下灵活调控它的行为，调控时长能够从数秒延伸至数十分钟。 该技术 整合了近红外光响应的双色正交发光的上转换纳米颗粒（odUCNPs）和光敏蛋白SOUL 。通过一次短暂的980纳米近红外照射，便可启动神经元兴奋并自行维持；如需终止，再以808纳米近红外照射使其复位。近红外光只在 “开”“关” 两个瞬间发挥作用，累计照射",
      "relatedTitles": [
        "科研人员开发神经活动无线“开关”"
      ],
