      "rawText": "首页 > 党建与科学文化 > 工作动态 11月11日，中国科学院国家纳米科学中心召开党委理论学习中心组学习会，传达学习党的二十届五中全会精神，研究部署贯彻落实举措。会议由中心党委书记欧龙新主持，党委委员、领导班子成员、所务委员参会。 欧龙新领学《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》，重点解读全会“七个坚持”原则和九个方面部署。会议指出，党的二十届五中全会是在建党105周年、“十五五”开局关键节点召开的重要会议，全会围绕持之以恒推进全面从严治党作出系统部署，为新征程上推进各项事业提供了根本遵循。与会人员围绕全会提出的全面从严治党新部署新要求，结合党风廉政建设、科研攻关、人才队伍建设等交流研讨。 会议强调，要把学习宣传贯彻党的二十届五中全会精神作为当前和今后一个时期的重大政治任务。一是要抓好分层分类宣贯学习，发挥中心组领学促学作用，依托支部“三会一课”、青年理论学习小组等组织党员深学细悟、交流研讨。二是要强化政治引领，持续涵养优良科研生态，结合专题整顿自查自纠、巩固拓展正确政绩观学习教育成果，把严的基调贯穿科研业务全过程。三是要坚持学用结合，紧紧围绕院“四个率先”目标任",
