      "rawText": "快科技11月17日消息，马斯克透露特斯拉最早或于12月启动车主Robotaxi试运营，允许个人车主将自有车辆接入其无人驾驶出租车网络接单，这是特斯拉首次开放个人车辆接入该网络。该愿景是马斯克2016年宏图计划中就提出的规划，今年9月特斯拉已开放Robotaxi意向登记表。目前特斯拉自有Robotaxi服务扩张迅速，9月Cybercab在奥斯汀投运，车队30天内规模涨8倍超300辆，服务已实现上线城市全天候运营，迈阿密服务区域近期扩近一倍，达拉斯计划11月启动。目前马斯克未披露试点具体城市、参与条件、车费分成等关键细节，现有条款暂禁车主私自将车辆用于相关运营，需等新规则公布。(AI生成)",
